  "privWho1": "Cook מופעל על ידי [השם המשפטי והכתובת למשלוח דואר של המפעיל]. לשאלות ובקשות בנושא פרטיות פנה אל [כתובת אימייל לפרטיות]. יש להשלים פרטים אלה לפני פתיחת ההרשמה.",
  "privWhat1": "כשאתה יוצר חשבון, אנחנו משתמשים באימייל שלך, במזהה חשבון, ברשומות אימות סיסמה ובסטטוס האימות כדי לספק ולאבטח את החשבון שלך. ספק האימות מטפל בסיסמאות כגיבובים מאובטחים; Cook אינו שומר סיסמאות קריאות. אנחנו שומרים את סידור המטבח, השפה שנבחרה, ערכת הנושא ויחידות המידה כדי לשחזר את ההגדרות שלך בכל המכשירים. לחשבון נדרשים אימייל וסיסמה; אפשר לעיין במתכונים גם בלי חשבון.",
  "privWhat2": "עיבוד החשבון וההגדרות נחוץ כדי לספק את שירות החשבון שביקשת (סעיף 6(1)(ב) ל-GDPR). רשומות מוגבלות לאבטחה ולמניעת ניצול לרעה עשויות להיות מעובדות על בסיס אינטרסים לגיטימיים (סעיף 6(1)(ו)), בכפוף להכרחיות ולאיזון. הודעות אימות ואיפוס סיסמה הן הודעות שירות, לא שיווק. תכונת החשבון אינה מוסיפה פרסום או ניתוח נתונים.",
  "privStorage1": "Cook משתמש ב-sessionStorage כדי להעביר את המטבח, התקדמות הבישול והבחירות שלך בין דפים באותה כרטיסייה. כשאתה מחובר, הוא שומר גם את הפעלת ההתחברות שלך. הדפדפן מוחק זאת בדרך כלל כשהפעלת הכרטיסייה מסתיימת, אבל שחזור הפעלות בדפדפן עשוי לשמור אותו. התנתקות מוחקת את נתוני הכרטיסייה של Cook. סגירת הודעת האחסון נשמרת בכרטיסייה זו בלבד. הסקריפטים של Cook עצמו אינם מגדירים קובצי Cookie. ספקי האחסון או השירות שלך עשויים לבצע עיבוד אבטחה משלהם, שיש לתעד לפני ההשקה.",
  "privStorage2": "„אישור” וכפתור הסגירה בהודעת האחסון רק סוגרים את ההודעה. הם אינם מאשרים ניתוח נתונים, פרסום או מעקב אופציונלי אחר. כל אחסון לא חיוני בעתיד יחייב בחירה נפרדת לפני שיתחיל, עם סירוב וביטול קלים באותה מידה.",
  "privOther1": "תכונת הדיבור הנוכחית ברשימת המתכונים מבקשת מ-country.is מדינה משוערת לפי כתובת ה-IP שלך כדי לבחור שפת זיהוי דיבור. אם אתה משתמש בזיהוי דרך המיקרופון, הדפדפן עשוי לשלוח שמע לספק זיהוי הדיבור שלו. אפשר גם להקליד את המצרכים. יש לבדוק את הספקים האלה, המדיניות שלהם והבסיס החוקי לתכונות אלה לפני ההשקה הציבורית.",
  "privProviders1": "ספק החשבונות המתוכנן: Supabase (‏PostgreSQL ואימות מנוהלים), עם אזור מסד נתונים שנבחר באיחוד האירופי. ספק אימייל: [ספק]. אחסון האתר: [ספק]. על המפעיל לאשר את הספקים בפועל, הסכמי העיבוד, מעבדי המשנה, מיקומי היומנים וכל העברה אל מחוץ לאזור הכלכלי האירופי. אזור מסד נתונים באיחוד האירופי אינו שולל כשלעצמו העברות בין-לאומיות. במידת הצורך, יש לציין את החלטת ההלימות או אמצעי ההגנה החוזיים החלים ואיך לקבל עותק שלהם.",
  "privRetention1": "הגדרות החשבון נשמרות כל עוד החשבון שלך פעיל. אפשר לבקש מחיקה דרך איש הקשר לפרטיות שצוין למעלה. לפני ההשקה על המפעיל לקבוע את תהליך הטיפול בבקשות מחיקה, את תפוגת החשבונות שלא אומתו ואת תקופות השמירה של יומני האבטחה והגיבויים. נתונים שנמחקו עשויים להישאר בגיבויים עם גישה מוגבלת עד תום תקופת השמירה המתועדת.",
  "privRights1": "בהתאם לתנאים החלים, אפשר לבקש גישה, תיקון, מחיקה, הגבלה או ניוד, או להתנגד לעיבוד המבוסס על אינטרס לגיטימי. פנה למפעיל שצוין למעלה; בדרך כלל עונים לבקשות תוך חודש, וכל הארכה חוקית מוסברת. אפשר להגיש תלונה לרשות הפיקוח, כולל ה-NAIH ההונגרית בכתובת naih.hu. Cook אינו משתמש בהגדרות החשבון לקבלת החלטות אוטומטיות בעלות השפעה משפטית או השפעה משמעותית דומה.",
